package profile

import (
	"math"
	"regexp"
	"slices"
	"strconv"
	"strings"
)

// ClientHints is how a browser answers a site's client hints opt-in
// (Accept-CH, Critical-CH, Clear-Site-Data): Chrome's. Generated by
// internal/harness/cmd/kindsgen from the client-hints capture; not
// hand-edited. Nil: the browser sends the hints its lists hold whatever a
// site asks for (Firefox and Safari ignore the opt-in), or the opt-in was
// not captured. See decision 0055.
type ClientHints struct {
	// Hints are every client hint a navigation sends once its origin opts
	// in to all of them, lowercase, in the order it sends them: the lists'
	// low-entropy hints included, which an opted-in navigation sends in
	// this run where its list has them.
	Hints []string `json:"hints"`
	// TableOrder is Hints in the order they enter the browser's header
	// table (Context.HeaderTable) on other requests, before the table's
	// other own headers (user-agent): the order the table's run comes out
	// in depends on it.
	TableOrder []string `json:"tableOrder"`
	// RestartAfter is the header after which a navigation restarted by
	// Critical-CH sends its hints ("accept"), instead of where its list
	// has the low-entropy ones.
	RestartAfter string `json:"restartAfter"`
	// FullVersion is the browser's full version ("156.0.8078.80"):
	// sec-ch-ua-full-version, and the browser's brands' versions in
	// sec-ch-ua-full-version-list.
	FullVersion string `json:"fullVersion"`
	// ChromiumFullVersion, when set, is the Chromium brand's version in
	// sec-ch-ua-full-version-list, where the browser is built on a
	// Chromium of another full version (Edge 157.0.4341.42 on
	// 157.0.8103.39); empty, the Chromium brand takes FullVersion (Chrome).
	ChromiumFullVersion string `json:"chromiumFullVersion,omitempty"`
	// Machine is the captured machine's: the values the hints carry
	// unless the client sets its own (Config.ClientHints).
	Machine Machine `json:"machine"`
}

// Machine is what a computer's client hints say about it: its system,
// screen, preferences and network. Chrome sends these values once a site
// opts in. Every field is required, in the form Chrome sends.
type Machine struct {
	// PlatformVersion is the system's version (sec-ch-ua-platform-version):
	// "27.0.1" for macOS 27.0.1, "10.0.0" or "19.0.0" on Windows, and empty
	// on Linux, where Chrome sends "".
	PlatformVersion string `json:"platformVersion"`
	// Arch is the CPU architecture (sec-ch-ua-arch): "arm" or "x86".
	Arch string `json:"arch"`
	// Bitness is the CPU's (sec-ch-ua-bitness): "64" or "32".
	Bitness string `json:"bitness"`
	// Model is the device model (sec-ch-ua-model): empty on desktops.
	Model string `json:"model,omitempty"`
	// WoW64 reports a 32-bit browser on 64-bit Windows (sec-ch-ua-wow64).
	WoW64 bool `json:"wow64,omitempty"`
	// FormFactors are the device's (sec-ch-ua-form-factors): "Desktop".
	FormFactors []string `json:"formFactors"`
	// DPR is the screen's device pixel ratio (dpr, sec-ch-dpr): 2 on a
	// Retina display.
	DPR float64 `json:"dpr"`
	// ViewportWidth and ViewportHeight are the window's layout viewport in
	// CSS pixels (viewport-width, sec-ch-viewport-width and
	// sec-ch-viewport-height).
	ViewportWidth  int `json:"viewportWidth"`
	ViewportHeight int `json:"viewportHeight"`
	// DeviceMemory is the memory in GiB, as Chrome rounds it to a power of
	// two (device-memory, sec-ch-device-memory).
	DeviceMemory float64 `json:"deviceMemory"`
	// ColorScheme is "light" or "dark" (sec-ch-prefers-color-scheme).
	ColorScheme string `json:"colorScheme"`
	// ReducedMotion and ReducedTransparency are "no-preference" or
	// "reduce" (sec-ch-prefers-reduced-motion,
	// sec-ch-prefers-reduced-transparency).
	ReducedMotion       string `json:"reducedMotion"`
	ReducedTransparency string `json:"reducedTransparency"`
	// Downlink is the bandwidth estimate in Mbps before Chrome's per-host
	// noise (downlink): the centre of the values captured.
	Downlink float64 `json:"downlink"`
	// ECT is the effective connection type (ect): "slow-2g", "2g", "3g"
	// or "4g".
	ECT string `json:"ect"`
}

// Client hints whose values depend on the connection, which the client
// computes per request (decision 0055).
const (
	HintRTT      = "rtt"
	HintDownlink = "downlink"
)

// lowEntropyHints are those every Chrome request carries unasked, with the
// values the profile's lists hold.
var lowEntropyHints = []string{
	"sec-ch-ua",
	"sec-ch-ua-mobile",
	"sec-ch-ua-platform",
}

// LowEntropyHint reports whether name (lowercase) is a client hint Chrome
// sends unasked.
func LowEntropyHint(name string) bool {
	return slices.Contains(lowEntropyHints, name)
}

// knownHints are the client hints mimicry can give a value: a profile's
// ClientHints.Hints are among them.
var knownHints = []string{
	"device-memory",
	"sec-ch-device-memory",
	"dpr",
	"sec-ch-dpr",
	"viewport-width",
	"sec-ch-viewport-width",
	"sec-ch-viewport-height",
	HintRTT,
	HintDownlink,
	"ect",
	"sec-ch-ua",
	"sec-ch-ua-mobile",
	"sec-ch-ua-full-version",
	"sec-ch-ua-arch",
	"sec-ch-ua-platform",
	"sec-ch-ua-platform-version",
	"sec-ch-ua-model",
	"sec-ch-ua-bitness",
	"sec-ch-ua-wow64",
	"sec-ch-ua-full-version-list",
	"sec-ch-ua-form-factors",
	"sec-ch-prefers-color-scheme",
	"sec-ch-prefers-reduced-motion",
	"sec-ch-prefers-reduced-transparency",
}

// ClientHintValue returns the value p's browser sends for client hint name
// (lowercase) on machine m: a low-entropy hint's from the navigation's
// list, the full versions from ClientHints, the rest from m. ok is false
// for the network hints (HintRTT, HintDownlink), which depend on the
// connection, and for a name p does not send.
func (p *Spec) ClientHintValue(name string, m *Machine) (value string, ok bool) {
	ch := p.ClientHints
	if ch == nil || !slices.Contains(ch.Hints, name) {
		return "", false
	}

	b := func(v bool) string {
		if v {
			return "?1"
		}

		return "?0"
	}
	num := func(v float64) string {
		return strconv.FormatFloat(v, 'f', -1, 64)
	}

	switch name {
	case "sec-ch-ua", "sec-ch-ua-mobile", "sec-ch-ua-platform":
		return navigationValue(p, name)
	case "sec-ch-ua-full-version":
		return strconv.Quote(ch.FullVersion), true
	case "sec-ch-ua-full-version-list":
		brands, ok := navigationValue(p, "sec-ch-ua")
		if !ok {
			return "", false
		}

		return fullVersionList(brands, ch.FullVersion, ch.ChromiumFullVersion)

	case "sec-ch-ua-arch":
		return strconv.Quote(m.Arch), true
	case "sec-ch-ua-bitness":
		return strconv.Quote(m.Bitness), true
	case "sec-ch-ua-model":
		return strconv.Quote(m.Model), true
	case "sec-ch-ua-platform-version":
		return strconv.Quote(m.PlatformVersion), true
	case "sec-ch-ua-wow64":
		return b(m.WoW64), true
	case "sec-ch-ua-form-factors":
		quoted := make([]string, len(m.FormFactors))
		for i, f := range m.FormFactors {
			quoted[i] = strconv.Quote(f)
		}

		return strings.Join(quoted, ", "), true

	case "dpr", "sec-ch-dpr":
		return num(m.DPR), true
	case "viewport-width", "sec-ch-viewport-width":
		return strconv.Itoa(m.ViewportWidth), true
	case "sec-ch-viewport-height":
		return strconv.Itoa(m.ViewportHeight), true
	case "device-memory", "sec-ch-device-memory":
		return num(m.DeviceMemory), true
	case "sec-ch-prefers-color-scheme":
		return m.ColorScheme, true
	case "sec-ch-prefers-reduced-motion":
		return m.ReducedMotion, true
	case "sec-ch-prefers-reduced-transparency":
		return m.ReducedTransparency, true
	case "ect":
		return m.ECT, true
	default:
		// The network hints.
		return "", false
	}
}

// navigationValue is the value of name in p's navigation list.
func navigationValue(p *Spec, name string) (string, bool) {
	for _, h := range p.Headers {
		if strings.EqualFold(h.Name, name) {
			return h.Value, true
		}
	}

	return "", false
}

// brandEntry is one entry of sec-ch-ua: a quoted brand and its quoted
// major version.
var brandEntry = regexp.MustCompile(`^("(?:[^"\\]|\\.)*");v="([0-9]+)"$`)

// fullVersionList is sec-ch-ua-full-version-list for sec-ch-ua's brands:
// a brand at the browser's major version takes the full version (the
// Chromium brand chromium, when set), any other (the GREASE brand) its
// major version with ".0.0.0".
func fullVersionList(brands, full, chromium string) (string, bool) {
	major, _, _ := strings.Cut(full, ".")
	entries := strings.Split(brands, ", ")
	out := make([]string, len(entries))

	for i, e := range entries {
		m := brandEntry.FindStringSubmatch(e)
		if m == nil {
			return "", false
		}

		v := m[2] + ".0.0.0"

		switch {
		case m[2] != major:
		case m[1] == `"Chromium"` && chromium != "":
			v = chromium
		default:
			v = full
		}

		out[i] = m[1] + ";v=" + strconv.Quote(v)
	}

	return strings.Join(out, ", "), true
}

// fullVersion is the form of ClientHints.FullVersion.
var fullVersion = regexp.MustCompile(`^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$`)

// checkClientHints checks p.ClientHints: known hints, each once, in a
// profile whose navigation lists place them and whose header table orders
// other requests' (decision 0055).
func (c *checker) checkClientHints(p *Spec) {
	ch := p.ClientHints
	if ch == nil {
		return
	}

	const path = "clientHints"

	if len(ch.Hints) == 0 {
		c.add(path+".hints", "is required")
	}

	seen := map[string]bool{}
	for i, h := range ch.Hints {
		switch {
		case !slices.Contains(knownHints, h):
			c.add(path+".hints["+strconv.Itoa(i)+"]", "%q is no client hint mimicry gives a value", h)
		case seen[h]:
			c.add(path+".hints["+strconv.Itoa(i)+"]", "%q is listed twice", h)
		}

		seen[h] = true
	}

	if len(ch.TableOrder) != len(ch.Hints) || slices.ContainsFunc(ch.TableOrder, func(h string) bool {
		return !seen[h]
	}) {
		c.add(path+".tableOrder", "must list hints in another order, each once")
	} else {
		in := map[string]bool{}
		for _, h := range ch.TableOrder {
			if in[h] {
				c.add(path+".tableOrder", "%q is listed twice", h)
			}

			in[h] = true
		}
	}

	for _, h := range lowEntropyHints {
		if _, ok := navigationValue(p, h); ok && !seen[h] {
			c.add(path+".hints", "must include %q, which the navigation sends", h)
		}
	}

	if !slices.ContainsFunc(p.Headers, func(h Header) bool {
		return LowEntropyHint(strings.ToLower(h.Name))
	}) {
		c.add(path, "needs a navigation list with a low-entropy hint, where the opted-in hints go")
	}

	if _, ok := navigationValue(p, ch.RestartAfter); !ok {
		c.add(path+".restartAfter", "%q is not in the navigation's list", ch.RestartAfter)
	}

	if !fullVersion.MatchString(ch.FullVersion) {
		c.add(path+".fullVersion", "%q must be four dot-separated numbers", ch.FullVersion)
	} else if brands, ok := navigationValue(p, "sec-ch-ua"); ok && seen["sec-ch-ua-full-version-list"] {
		if _, ok := fullVersionList(brands, ch.FullVersion, ch.ChromiumFullVersion); !ok {
			c.add(path+".fullVersion", "the navigation's sec-ch-ua %q is no brand list", brands)
		}
	}

	if ch.ChromiumFullVersion != "" && !fullVersion.MatchString(ch.ChromiumFullVersion) {
		c.add(path+".chromiumFullVersion", "%q must be four dot-separated numbers", ch.ChromiumFullVersion)
	}

	if p.Context == nil || p.Context.HeaderTable == nil {
		c.add(path, "needs context.headerTable, which orders the hints of requests other than navigations")
	}

	c.checkMachine(path+".machine", &ch.Machine)
	c.checkPlatformVersion(path+".machine.platformVersion", p.Platform, ch.Machine.PlatformVersion)
}

// checkPlatformVersion checks a machine's platformVersion against the
// platform of the profile it goes with: Chrome on Linux sends none, and
// every other platform a version.
func (c *checker) checkPlatformVersion(path, platform, version string) {
	switch linux := platform == "linux"; {
	case linux && version != "":
		c.add(path, "%q must be empty: Chrome on Linux sends no version", version)
	case !linux && version == "":
		c.add(path, "is required off Linux")
	}
}

// Validate checks m as Config.ClientHints takes it: every field set, in
// the form Chrome sends. It returns a *ValidationError, or nil.
// PlatformVersion may be empty or a version here; CheckPlatformVersion
// checks it against a profile's platform.
func (m *Machine) Validate() error {
	c := &checker{}
	c.checkMachine("machine", m)

	return c.err()
}

// CheckPlatformVersion checks m.PlatformVersion against platform, the
// Platform of the profile m goes with: empty on "linux", where Chrome
// sends no version, and set on every other platform. It returns a
// *ValidationError at machine.platformVersion, or nil.
func CheckPlatformVersion(platform string, m *Machine) error {
	c := &checker{}
	c.checkPlatformVersion("machine.platformVersion", platform, m.PlatformVersion)

	return c.err()
}

// platformVersion is the form of Machine.PlatformVersion: empty, as Chrome
// on Linux sends it, or the system's version.
var platformVersion = regexp.MustCompile(`^([0-9]+(\.[0-9]+){0,3})?$`)

// formFactors are the values Chrome's sec-ch-ua-form-factors takes.
var formFactors = []string{
	"Automotive",
	"Desktop",
	"EInk",
	"Mobile",
	"Tablet",
	"Watch",
	"XR",
}

// ectValues are the values of ect.
var ectValues = []string{
	"slow-2g",
	"2g",
	"3g",
	"4g",
}

func (c *checker) checkMachine(path string, m *Machine) {
	if !platformVersion.MatchString(m.PlatformVersion) {
		c.add(path+".platformVersion", "%q must be empty or dot-separated numbers", m.PlatformVersion)
	}

	if m.Arch != "arm" && m.Arch != "x86" {
		c.add(path+".arch", "%q must be \"arm\" or \"x86\"", m.Arch)
	}

	if m.Bitness != "64" && m.Bitness != "32" {
		c.add(path+".bitness", "%q must be \"64\" or \"32\"", m.Bitness)
	}

	if strings.ContainsFunc(m.Model, func(r rune) bool {
		return r < 0x20 || r > 0x7e || r == '"' || r == '\\'
	}) {
		c.add(path+".model", "%q must be printable ASCII without quotes or backslashes", m.Model)
	}

	if len(m.FormFactors) == 0 {
		c.add(path+".formFactors", "is required")
	}

	for i, f := range m.FormFactors {
		if !slices.Contains(formFactors, f) {
			c.add(path+".formFactors["+strconv.Itoa(i)+"]", "%q must be one of %s", f, strings.Join(formFactors, ", "))
		}
	}

	if !(m.DPR > 0 && m.DPR <= 16) {
		c.add(path+".dpr", "%v must be above 0 and at most 16", m.DPR)
	}

	if m.ViewportWidth <= 0 || m.ViewportHeight <= 0 {
		c.add(path+".viewportWidth", "the viewport (%d by %d) must be positive", m.ViewportWidth, m.ViewportHeight)
	}

	if frac, exp := math.Frexp(m.DeviceMemory); frac != 0.5 || exp < -1 || exp > 8 {
		c.add(path+".deviceMemory", "%v must be a power of two from 0.25 to 128", m.DeviceMemory)
	}

	if m.ColorScheme != "light" && m.ColorScheme != "dark" {
		c.add(path+".colorScheme", "%q must be \"light\" or \"dark\"", m.ColorScheme)
	}

	for _, f := range []struct {
		name, value string
	}{
		{"reducedMotion", m.ReducedMotion},
		{"reducedTransparency", m.ReducedTransparency},
	} {
		if f.value != "no-preference" && f.value != "reduce" {
			c.add(path+"."+f.name, "%q must be \"no-preference\" or \"reduce\"", f.value)
		}
	}

	if !(m.Downlink > 0 && m.Downlink <= 10) {
		c.add(path+".downlink", "%v must be above 0 and at most 10 (Mbps; Chrome caps it there)", m.Downlink)
	}

	if !slices.Contains(ectValues, m.ECT) {
		c.add(path+".ect", "%q must be one of %s", m.ECT, strings.Join(ectValues, ", "))
	}
}
